"""Confusing word pairs and everyday phrases for the tutor's guide (original, 2026-11-18).

Each tuple matches create-guides.py: id suffix, category, question (vi), question (en), answer (vi),
answer (en), other ways to ask. Word answers give each meaning, an example and a way to tell them apart;
phrase answers give a handful of natural sentences for one situation.
"""


def pair(slug, a, b, vi, en, keys):
    q_vi = f"{a} và {b} khác nhau thế nào?"
    q_en = f"What is the difference between {a} and {b}?"
    return (f"w-{slug}", "words", q_vi, q_en, vi, en, [f"{a} {b}", f"{a} hay {b}", f"{a} or {b}"] + keys)


